  const SRC = 'https://github.com/addyosmani/agent-skills', RAW = 'https://raw.githubusercontent.com/addyosmani/agent-skills/main/skills/';
  const INDEX = [{"name": "api-and-interface-design", "desc": "Guides stable API and interface design.", "full": "Guides stable API and interface design. Use when designing APIs, module boundaries, or any public interface. Use when creating REST or GraphQL endpoints, defining type contracts between modules, or establishing boundaries between frontend and backend."}, {"name": "browser-testing-with-devtools", "desc": "Tests in real browsers via Chrome DevTools MCP.", "full": "Tests in real browsers via Chrome DevTools MCP. Use when building or debugging anything that runs in a browser. Use when you need to inspect the DOM, capture console errors, analyze network requests, profile performance, or verify visual output with real runtime data. Requires the chrome-devtools MCP server to be configured."}, {"name": "ci-cd-and-automation", "desc": "Automates CI/CD pipeline setup.", "full": "Automates CI/CD pipeline setup. Use when setting up or modifying build and deployment pipelines. Use when you need to automate quality gates, configure test runners in CI, or establish deployment strategies."}, {"name": "code-review-and-quality", "desc": "Conducts multi-axis code review.", "full": "Conducts multi-axis code review. Use before merging any change. Use when reviewing code written by yourself, another agent, or a human. Use when you need to assess code quality across multiple dimensions before it enters the main branch. Use when asked to review a diff or a pull request, even when the diff is pasted inline."}, {"name": "code-simplification", "desc": "Simplifies code for clarity.", "full": "Simplifies code for clarity. Use when refactoring code for clarity without changing behavior. Use when code works but is harder to read, maintain, or extend than it should be. Use when reviewing code that has accumulated unnecessary complexity. Use when asked to simplify, clean up, or reduce the nesting of a function or module that already works, even when the code is pasted inline and nothing els"}, {"name": "constraint-driven-development", "desc": "Establishes a project's quality bar as a written contract and stops agents quietly lowering it.", "full": "Establishes a project's quality bar as a written contract and stops agents quietly lowering it. Interviews the user on which dimensions matter, supplies sane default thresholds when they have no number in mind, records everything in CONSTRAINTS.md, and watches the diff for a weakened bar — new @ts-ignore or eslint-disable suppressions, skipped or deleted tests, assertions stripped out, unimplement"}, {"name": "context-engineering", "desc": "Optimizes agent context setup.", "full": "Optimizes agent context setup. Use when starting a new session, when agent output quality degrades, when switching between tasks, or when you need to configure rules files and context for a project."}, {"name": "debugging-and-error-recovery", "desc": "Guides systematic root-cause debugging.", "full": "Guides systematic root-cause debugging. Use when tests fail, builds break, something that worked yesterday broke, behavior doesn't match expectations, or you encounter any unexpected error. Use when you need to figure out what broke and why — a systematic approach to finding and fixing the root cause rather than guessing."}, {"name": "deprecation-and-migration", "desc": "Manages deprecation and migration.", "full": "Manages deprecation and migration. Use when removing old systems, APIs, or features. Use when migrating users from one implementation to another. Use when migrating a database schema in production, such as renaming or dropping a column without downtime (expand/contract). Use when deciding whether to maintain or sunset existing code."}, {"name": "documentation-and-adrs", "desc": "Records decisions and documentation.", "full": "Records decisions and documentation. Use when you need to document an architecture decision (ADR) or the reasoning behind a design choice, when changing public APIs, shipping features, or when you need to record context that future engineers and agents will need to understand the codebase."}, {"name": "doubt-driven-development", "desc": "Subjects every non-trivial decision to a fresh-context adversarial review before it stands.", "full": "Subjects every non-trivial decision to a fresh-context adversarial review before it stands. Use when you want every assumption cross-examined before proceeding, when stress-testing a plan for hidden failure modes, when correctness matters more than speed, when working in unfamiliar code, when stakes are high (production auth, security-sensitive logic, a high-stakes migration, irreversible operatio"}, {"name": "frontend-ui-engineering", "desc": "Builds production-quality, accessible, responsive user-facing UIs.", "full": "Builds production-quality, accessible, responsive user-facing UIs. Use when building or modifying interfaces and pages, creating components, implementing layouts, meeting WCAG accessibility requirements, managing state, or when the output needs to look and feel production-quality rather than AI-generated."}, {"name": "git-workflow-and-versioning", "desc": "Structures git workflow practices.", "full": "Structures git workflow practices. Use when making any code change. Use when committing, branching, resolving conflicts, splitting uncommitted work in a messy working tree into clean atomic commits, opening or reviewing a pull request (PR), pushing to a remote, or when you need to organize work across multiple parallel streams. Use when cutting a release, choosing a semantic version bump, tagging,"}, {"name": "idea-refine", "desc": "Refines raw ideas into sharp, actionable concepts through structured divergent and convergent thinking.", "full": "Refines raw ideas into sharp, actionable concepts through structured divergent and convergent thinking. Use when an idea is still vague, when you need to stress-test assumptions before committing to a plan, or when you want to expand options before converging on one. Triggers on \"ideate\", \"refine this idea\", or \"stress-test my plan\"."}, {"name": "incremental-implementation", "desc": "Delivers changes incrementally in thin, verifiable slices.", "full": "Delivers changes incrementally in thin, verifiable slices. Use when implementing any feature or change that touches more than one file, or when picking up the next task from a plan. Use when rolling a change out behind a feature flag, when you're about to write a large amount of code at once, or when a task feels too big to land in one step."}, {"name": "interview-me", "desc": "Extracts what the user actually wants instead of what they think they should want.", "full": "Extracts what the user actually wants instead of what they think they should want. Achieves this through one-question-at-a-time interview until ~95% confidence about the underlying intent. Use when an ask is underspecified (\"build me X\" without \"for whom\" or \"why now\"), when the user explicitly invokes (\"interview me\", \"grill me\", \"are we sure?\", \"stress-test my thinking\"), or when you catch yours"}, {"name": "observability-and-instrumentation", "desc": "Instruments code so production behavior is visible and diagnosable.", "full": "Instruments code so production behavior is visible and diagnosable. Use when adding logging, metrics, tracing, or alerting. Use when shipping any feature that runs in production and you need evidence it works. Use when production issues are reported but you can't tell what happened from the available data."}, {"name": "performance-optimization", "desc": "Optimizes application performance across frontend, backend, queries, and databases.", "full": "Optimizes application performance across frontend, backend, queries, and databases. Use when performance requirements exist, when you suspect performance regressions, when Core Web Vitals or load times need improvement, when N+1 query patterns need fixing, or when profiling reveals bottlenecks."}, {"name": "planning-and-task-breakdown", "desc": "Breaks work into ordered tasks.", "full": "Breaks work into ordered tasks. Use when you have a spec or clear requirements and need to break work into implementable tasks. Use when a task feels too large to start, when you need to estimate scope, or when parallel work is possible."}, {"name": "security-and-hardening", "desc": "Hardens code against vulnerabilities.", "full": "Hardens code against vulnerabilities. Use when auditing an input handler for vulnerabilities, when handling user input, authentication, data storage, or external integrations, or when checking a login flow is safe against the OWASP Top Ten. Use when building any feature that accepts untrusted data, manages user sessions or session cookies, or interacts with third-party services. Use when auditing "}, {"name": "shipping-and-launch", "desc": "Prepares production launches.", "full": "Prepares production launches. Use when preparing to deploy to production, or when asking what needs to be in place before shipping. Use when you need a pre-launch checklist, when setting up monitoring, when planning a staged rollout, or when you need a rollback strategy."}, {"name": "source-driven-development", "desc": "Grounds every implementation decision in official documentation.", "full": "Grounds every implementation decision in official documentation. Use when you want to verify an approach against the official docs before implementing it, or when you want authoritative, source-cited code free from outdated patterns. Use when building with any framework or library where correctness matters."}, {"name": "spec-driven-development", "desc": "Creates specs before coding.", "full": "Creates specs before coding. Use when starting a new project, feature, or significant change and no specification exists yet. Use when drafting a PRD or requirements document with objectives and scope, or when requirements are unclear, ambiguous, or only exist as a vague idea. Use when a single requirement spans several independently testable capabilities and needs decomposing into a capability ma"}, {"name": "test-driven-development", "desc": "Drives development with tests using the red-green-refactor loop.", "full": "Drives development with tests using the red-green-refactor loop. Use when implementing any logic, fixing any bug, or changing any behavior. Use when you need to prove that code works, when a bug report arrives, or when you're about to modify existing functionality. Use when asked to add tests to a function, fix a bug in it or change its behavior, even when the code is pasted inline and the request"}, {"name": "using-agent-skills", "desc": "Discovers and invokes agent skills.", "full": "Discovers and invokes agent skills. Use when starting a session, or when you need to decide which skill or workflow applies to the piece of work at hand. This is the meta-skill that governs how all other skills are discovered and invoked."}];
